{
  "units": [
    {
      "quote": "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If there are material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity, such discrepancies must be documented by submitting one or more of the documents listed in this section."
    },
    {
      "quote": "(see an exception for married names in 8 FAM 403.1-4(C))",
      "scope_quotes": [
        "Material discrepancies between the name recorded on the application, the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality, or the evidence of identity must be documented by submission of one or more of the documents listed in this section"
      ],
      "kind": "exception",
      "meaning": "An exception to the requirement to document material name discrepancies using the documents listed in this section applies to married names as provided in 8 FAM 403.1-4(C)."
    },
    {
      "quote": "(1) Court orders or decrees:",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, court orders or decrees constitute an acceptable means of documenting a material name change."
    },
    {
      "quote": "(a) Name change orders; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, name change orders are acceptable court orders or decrees for documenting a material name change."
    },
    {
      "quote": "(b) Divorce decrees;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):",
        "(1) Court orders or decrees:"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, divorce decrees are acceptable court orders or decrees for documenting a material name change."
    },
    {
      "quote": "(2) Certificates of naturalization;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, certificates of naturalization are an acceptable means of documenting a material name change."
    },
    {
      "quote": "(3) Marriage certificates;",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, marriage certificates are an acceptable means of documenting a material name change."
    },
    {
      "quote": "(4) Documentation demonstrating change of name by operation of state law; or",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, documentation demonstrating a change of name by operation of state law is an acceptable means of documenting a material name change."
    },
    {
      "quote": "(5) Documentation of customary usage.",
      "scope_quotes": [
        "Acceptable means of documenting a material name change include (per 22 CFR 51.25):"
      ],
      "kind": "alternative",
      "meaning": "Under 22 CFR 51.25, documentation of customary usage is an acceptable means of documenting a material name change."
    }
  ]
}
